// S3-03 - Recomendacion de venta GMML + MMF2
// Mode: Run Once for All Items

const filas = $input.all()
  .map(i => i.json ?? {})
  .filter(r =>
    ['GMML', 'MMF2'].includes(r.mercado) &&
    r.producto &&
    r.precio_actual != null
  );

const fuente = $('Switch1').first().json;

const clase = typeof fuente.output === 'string'
  ? JSON.parse(fuente.output)
  : (fuente.output ?? fuente);

const pregunta = String(
  $('Webhook').first().json.body?.pregunta ?? ''
);

const buscado = clase.producto || null;

const num = v =>
  v === null || v === undefined || v === ''
    ? null
    : (Number.isFinite(Number(v)) ? Number(v) : null);

const normal = s => String(s ?? '')
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .trim();

const palabras = s =>
  normal(s).split(/[^a-z0-9]+/).filter(Boolean);

const textoPregunta = normal(pregunta);

const mencionaGMML =
  /\bgmml\b|gran mercado mayorista|mercado de verduras/.test(
    textoPregunta
  );

const mencionaMMF2 =
  /\bmmf2\b|\bmmf\b|mercado de frutas|mayorista de frutas/.test(
    textoPregunta
  );

const pideComparacion =
  /compar|ambos mercados|dos mercados|entre mercados/.test(
    textoPregunta
  );

const pideAmbos =
  pideComparacion || (mencionaGMML && mencionaMMF2);

const mercadoSolicitado = pideAmbos
  ? null
  : mencionaMMF2
    ? 'MMF2'
    : mencionaGMML
      ? 'GMML'
      : null;

const nombreMercado = m =>
  m === 'GMML'
    ? 'Gran Mercado Mayorista de Lima (GMML)'
    : 'Mercado Mayorista de Frutas N.º 2 (MMF2)';

function resumen(d) {
  return {
    mercado: d.mercado,
    nombre_mercado: nombreMercado(d.mercado),

    producto: d.producto,
    producto_id: d.producto_id ?? null,
    unidad: d.unidad,

    fecha_ultimo_registro: d.fecha_ultimo_registro,

    precio_actual: num(d.precio_actual),
    precio_anterior: num(d.precio_anterior),
    precio_promedio_7: num(d.precio_promedio_7),
    precio_promedio_30: num(d.precio_promedio_30),

    tendencia_precio: d.tendencia_precio,

    fecha_ultimo_volumen: d.fecha_ultimo_volumen,
    volumen_ultimo_t: num(d.volumen_ultimo_t),
    volumen_actual_t: num(d.volumen_actual_t),
    volumen_promedio_7_t: num(d.volumen_promedio_7_t),
    volumen_promedio_30_t: num(d.volumen_promedio_30_t),

    registros_precio_7: num(d.registros_precio_7) ?? 0,
    registros_volumen_7: num(d.registros_volumen_7) ?? 0,

    total_registros_precio:
      num(d.total_registros_precio) ?? 0,

    total_registros_volumen:
      num(d.total_registros_volumen) ?? 0,

    dias_desde_precio: num(d.dias_desde_precio),

    desfase_precio_volumen_dias:
      num(d.desfase_precio_volumen_dias),

    desde: d.desde,
    hasta: d.hasta
  };
}

const lista = filas.map(resumen);

const disponibles = mercadoSolicitado
  ? lista.filter(r => r.mercado === mercadoSolicitado)
  : lista;

const mercadosConsultados = mercadoSolicitado
  ? [mercadoSolicitado]
  : ['GMML', 'MMF2'];

const mercadosConDatos = [...new Set(
  disponibles.map(r => r.mercado)
)];

// =======================================
// CONSULTA GENERAL DE LOS MERCADOS
// =======================================

/*
 * AGROSMART S3-03
 * Resumen general de precios por mercado
 */

if (!buscado) {

  const fechaReferencia = String(
    clase.fecha ??
    $('Webhook').first().json.body?.fecha ??
    ''
  );

  const preguntaNorm = normal(pregunta);

  const pideGMML = /\bgmml\b/.test(preguntaNorm);
  const pideMMF2 = /\bmmf2\b/.test(preguntaNorm);

  const mercadosSolicitados =
    pideGMML && !pideMMF2 ? ['GMML'] :
    pideMMF2 && !pideGMML ? ['MMF2'] :
    ['GMML', 'MMF2'];

  const fechaValor = v => String(v ?? '').slice(0, 10);

  const registros = filas
    .filter(r =>
      mercadosSolicitados.includes(r.mercado) &&
      normal(r.unidad) === 'kilogramo' &&
      num(r.precio_actual) > 0
    )
    .map(r => {

      const actual = num(r.precio_actual);
      const anterior = num(r.precio_anterior);

      const variacion =
        anterior !== null && anterior > 0
          ? ((actual - anterior) / anterior) * 100
          : null;

      return {
        mercado: r.mercado,
        producto: r.producto,
        unidad: r.unidad,
        precio_actual: actual,
        precio_anterior: anterior,
        variacion_porcentual: variacion,
        fecha: fechaValor(r.fecha_ultimo_registro),
        tendencia_precio: r.tendencia_precio
      };
    });

  const resultado = {};

  for (const mercado of mercadosSolicitados) {

    // Utilizar los registros mas recientes
    // disponibles de ese mercado.
    const datosMercado = registros.filter(
      r => r.mercado === mercado
    );

    const ultimaFecha = datosMercado
      .map(r => r.fecha)
      .filter(Boolean)
      .sort()
      .at(-1) ?? null;

    const datos = datosMercado.filter(
      r => r.fecha === ultimaFecha
    );

    const caros = [...datos]
      .sort((a, b) => b.precio_actual - a.precio_actual)
      .slice(0, 2);

    const baratos = [...datos]
      .sort((a, b) => a.precio_actual - b.precio_actual)
      .slice(0, 2);

    const conVariacion = datos.filter(
      r => r.variacion_porcentual !== null
    );

    const alzas = [...conVariacion]
      .filter(r => r.variacion_porcentual > 0)
      .sort((a, b) =>
        b.variacion_porcentual - a.variacion_porcentual
      )
      .slice(0, 2);

    const bajas = [...conVariacion]
      .filter(r => r.variacion_porcentual < 0)
      .sort((a, b) =>
        a.variacion_porcentual - b.variacion_porcentual
      )
      .slice(0, 2);

    resultado[mercado] = {
      fecha_registros: ultimaFecha,
      productos_analizados: datos.length,
      productos_mas_caros: caros,
      productos_mas_baratos: baratos,
      mayores_alzas: alzas,
      mayores_bajas: bajas
    };
  }

  return [{
    json: {
      modo: 'general',
      pregunta_usuario: pregunta,
      fecha_solicitada: fechaReferencia || null,
      mercados_consultados: mercadosSolicitados,
      comparacion_mercados: resultado,
      estado_recomendacion: 'no_aplica',
      instrucciones:
        'Generar resumen corto por mercado. ' +
        'Mostrar hasta 2 productos mas caros, ' +
        '2 mas baratos, 2 mayores alzas y ' +
        '2 mayores bajas. ' +
        'Indicar precio en S/kg y porcentaje ' +
        'de variacion cuando exista. ' +
        'No inventar registros ni porcentajes. ' +
        'No recomendar vender o comprar para ' +
        'todo el mercado.'
    }
  }];
}

// =======================================
// CONSULTA DE PRODUCTO ESPECIFICO
// =======================================

// Coincidencia por palabras completas.
// Evita confundir papa con papaya.

const buscadas = palabras(buscado);

const exactos = disponibles.filter(
  r => normal(r.producto) === normal(buscado)
);

const candidatos = exactos.length
  ? exactos
  : disponibles.filter(r => {
      const encontradas = palabras(r.producto);

      return buscadas.every(
        p => encontradas.includes(p)
      );
    });

// Detectar presentacion comercial

let unidadPedida = null;

if (/\batados?\b/.test(textoPregunta)) {
  unidadPedida = 'atado';

} else if (/\bdocenas?\b/.test(textoPregunta)) {
  unidadPedida = 'docena';

} else if (/\b(kilogramos?|kilos?|kg)\b/.test(textoPregunta)) {
  unidadPedida = 'kilogramo';
}

let seleccionados = unidadPedida
  ? candidatos.filter(
      r => normal(r.unidad) === unidadPedida
    )
  : candidatos;

// Priorizar kilogramo si solo existe una
// coincidencia por mercado y variedad.

let seleccionAutomatica = false;

if (!unidadPedida && seleccionados.length > 1) {

  const enKilogramos = seleccionados.filter(
    r => normal(r.unidad) === 'kilogramo'
  );

  if (
    enKilogramos.length === 1 &&
    seleccionados.every(
      r => normal(r.producto) === normal(enKilogramos[0].producto) &&
           r.mercado === enKilogramos[0].mercado
    )
  ) {
    seleccionados = enKilogramos;
    seleccionAutomatica = true;
  }
}

// =======================================
// EVALUAR CADA COINCIDENCIA
// =======================================

function evaluar(d) {

  const razones = [];

  if (d.registros_precio_7 < 5) {
    razones.push(
      'Hay menos de 5 registros recientes de precio.'
    );
  }

  if (d.registros_volumen_7 < 3) {
    razones.push(
      'Hay menos de 3 registros de volumen para comparar.'
    );
  }

  if (
    d.precio_anterior === null ||
    d.precio_promedio_7 === null ||
    d.precio_promedio_7 <= 0 ||
    d.precio_actual <= 0
  ) {
    razones.push(
      'No existe una comparacion reciente de precios valida.'
    );
  }

  if (
    d.volumen_ultimo_t === null ||
    d.volumen_promedio_7_t === null ||
    d.volumen_promedio_7_t <= 0
  ) {
    razones.push(
      'Falta volumen reciente o su promedio comparable.'
    );
  }

  if (
    d.dias_desde_precio === null ||
    d.dias_desde_precio > 7
  ) {
    razones.push(
      'El ultimo precio tiene mas de 7 dias de antiguedad.'
    );
  }

  if (
    d.desfase_precio_volumen_dias === null ||
    d.desfase_precio_volumen_dias > 7
  ) {
    razones.push(
      'El ultimo volumen no corresponde ' +
      'a un periodo comparable con el precio.'
    );
  }

  const suficiente = razones.length === 0;

  let decision = null;
  let razonesDecision = [];

  if (suficiente) {

    const relacionPrecio =
      d.precio_actual / d.precio_promedio_7;

    const relacionVolumen =
      d.volumen_ultimo_t / d.volumen_promedio_7_t;

    if (
      relacionPrecio >= 1.05 &&
      relacionVolumen <= 0.90
    ) {
      decision = 'Vender ahora';

    } else if (
      relacionPrecio <= 0.95 &&
      relacionVolumen >= 1.10
    ) {
      decision = 'Esperar y monitorear';

    } else {
      decision = 'Vender parcialmente y monitorear';
    }

    razonesDecision = [
      `Precio: S/ ${d.precio_actual} por ${d.unidad}; ` +
      `promedio reciente: S/ ${d.precio_promedio_7}.`,

      `Volumen: ${d.volumen_ultimo_t} t; ` +
      `promedio reciente: ${d.volumen_promedio_7_t} t.`,

      `Tendencia: ${d.tendencia_precio}.`
    ];
  }

  return {
    mercado: d.mercado,
    nombre_mercado: d.nombre_mercado,

    producto: d.producto,
    unidad: d.unidad,

    datos: d,

    estado_recomendacion:
      suficiente ? 'suficiente' : 'insuficiente',

    faltantes: razones,
    decision_sugerida: decision,
    razones_decision: razonesDecision
  };
}

// =======================================
// RESPUESTA DE PRODUCTO
// =======================================

const evaluaciones = seleccionados.map(evaluar);

// Si hay varias variedades, no inventar una
// decision unica para todas ellas.

const unaCoincidencia = evaluaciones.length === 1;

return [{
  json: {
    modo: 'especifico',
    pregunta_usuario: pregunta,
    producto_solicitado: buscado,

    mercado: mercadoSolicitado ?? 'AMBOS',
    mercados_consultados: mercadosConsultados,
    mercados_con_datos: [...new Set(
      evaluaciones.map(e => e.mercado)
    )],

    productos_encontrados: evaluaciones.length,

    datos: unaCoincidencia
      ? evaluaciones[0].datos
      : null,

    resultados_por_mercado: evaluaciones,

    estado_recomendacion: unaCoincidencia
      ? evaluaciones[0].estado_recomendacion
      : 'multiple',

    decision_sugerida: unaCoincidencia
      ? evaluaciones[0].decision_sugerida
      : null,

    faltantes: unaCoincidencia
      ? evaluaciones[0].faltantes
      : [],

    razones_decision: unaCoincidencia
      ? evaluaciones[0].razones_decision
      : [],

    unidad_seleccionada:
      unaCoincidencia ? evaluaciones[0].unidad : null,

    unidad_seleccionada_por_defecto:
      seleccionAutomatica,

    instrucciones:
      'Si existen varias variedades o mercados, ' +
      'presentar los resultados por separado. ' +
      'No emitir una recomendacion unica para ' +
      'productos o mercados diferentes. ' +
      'No afirmar que un mercado carece del producto ' +
      'si simplemente faltan registros.',

    nota:
      'El clima no fue incluido en esta ejecucion.'
  }
}];

