parameters.jsCode:
const preguntaOriginal =
  $('Webhook').first().json.body.pregunta || '';

const pregunta = preguntaOriginal
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .trim();


// ==========================================
// 1. SOLICITUDES SENSIBLES / PELIGROSAS
// ==========================================

const patronesBloqueados = [
  /codigo fuente/,
  /source code/,
  /api[\s_-]*key/,
  /clave api/,
  /contrasena/,
  /password/,
  /credenciales/,
  /secret[\s_-]*key/,
  /token secreto/,
  /variables? de entorno/,
  /\.env/,
  /connection string/,
  /cadena de conexion/,
  /prompt interno/,
  /system prompt/,
  /instrucciones internas/,
  /ignora .*instrucciones/,
  /ignora .*reglas/,
  /olvida .*instrucciones/,
  /muestrame .*prompt/,
  /dame .*prompt/,
  /revela .*prompt/,
  /muestrame .*credenciales/,
  /dame .*credenciales/,
  /postgres.*contrasena/,
  /openrouter.*key/,
  /langfuse.*key/,
  /maptiler.*key/
];

const esPeligrosa =
  patronesBloqueados.some(patron =>
    patron.test(pregunta)
  );


// ==========================================
// 2. DOMINIO PERMITIDO DE AGROSMART
// ==========================================

const patronesAgroSmart = [

  // PRECIOS Y MERCADO
  /precio/,
  /cuesta/,
  /costo/,
  /costaba/,
  /cotiz/,
  /mercado/,
  /mayorista/,
  /vender/,
  /venta/,
  /tendencia/,
  /subira/,
  /bajara/,
  /alza/,
  /baja/,

  // VOLUMEN Y ABASTECIMIENTO
  /volumen/,
  /tonelada/,
  /kilo/,
  /kg/,
  /ingreso/,
  /ingreso/,
  /ingresaron/,
  /abastecimiento/,
  /desabastecimiento/,
  /camion/,
  /oferta/,

  // AGRICULTURA
  /agricola/,
  /agricultura/,
  /cultivo/,
  /producto/,
  /cosecha/,
  /productor/,

  // CLIMA
  /clima/,
  /climatic/,
  /condiciones climatic/,
  /temperatur/,
  /lluvia/,
  /precipit/,
  /humedad/,
  /sequia/,
  /helada/,
  /evapotranspir/,
  /meteorolog/,
  /junin/,
  // SATELITAL
  /satelit/,
  /mapa/,
  /espacial/,

  // RAG / BOLETINES
  /boletin/,
  /midagri/,
  /gmml/,
  /gran mercado mayorista/,
  /mmf2/,
  /mercado de frutas/,

  // PRODUCTOS COMUNES
  /papa/,
  /cebolla/,
  /coliflor/,
  /tomate/,
  /zanahoria/,
  /beterraga/,
  /yuca/,
  /maiz/,
  /camote/,
  /aji/,
  /rocoto/,
  /zapallo/,
  /lechuga/,
  /acelga/
];

const perteneceAgroSmart =
  patronesAgroSmart.some(patron =>
    patron.test(pregunta)
  );


// ==========================================
// 3. DECISIÓN FINAL
// ==========================================

let consultaPermitida = true;
let motivoBloqueo = null;

if (esPeligrosa) {

  consultaPermitida = false;
  motivoBloqueo =
    'solicitud_sensible_o_interna';

}
else if (!perteneceAgroSmart) {

  consultaPermitida = false;
  motivoBloqueo =
    'fuera_de_alcance';

}


// ==========================================
// 4. SALIDA
// ==========================================

return [{
  json: {
    ...$json,
    consulta_permitida: consultaPermitida,
    motivo_bloqueo: motivoBloqueo
  }
}];

