parameters.jsCode:
/*
 AGROSMART INSIGHTS - WF2
 NORMALIZAR CLASIFICACION

 Prioridades:
 1. Consultas documentales RAG (Pipeline 6).
 2. Monitoreo satelital externo (WF3).
 3. Clima y efectos sobre cultivos.
 4. Volumen de ingreso.
 5. Precios semanales.
 6. Precios generales y comparaciones.
 7. Clasificacion original del agente.

 Compatible con AI Agent2 y AI Agent3.
*/

// ========================================
// 1. EXTRAER Y VALIDAR JSON DEL AGENTE
// ========================================

function extraerObjeto(valor) {

  if (
    valor !== null &&
    typeof valor === 'object' &&
    !Array.isArray(valor)
  ) {
    return { ...valor };
  }

  if (typeof valor !== 'string' || !valor.trim()) {
    throw new Error(
      'La salida del agente esta vacia o no es JSON.'
    );
  }

  let texto = valor.trim().replace(/^\uFEFF/, '');

  const bloque = texto.match(
    /```(?:json)?\s*([\s\S]*?)\s*```/i
  );

  if (bloque) {
    texto = bloque[1].trim();
  } else {
    const inicio = texto.indexOf('{');
    const fin = texto.lastIndexOf('}');

    if (inicio >= 0 && fin > inicio) {
      texto = texto.slice(inicio, fin + 1);
    }
  }

  let datos;

  try {
    datos = JSON.parse(texto);
  } catch (e) {
    throw new Error(
      'El agente no devolvio JSON valido: ' +
      e.message
    );
  }

  if (
    !datos ||
    typeof datos !== 'object' ||
    Array.isArray(datos)
  ) {
    throw new Error(
      'La clasificacion debe ser un objeto JSON.'
    );
  }

  const categorias = [
    'precio_puntual',
    'volumen_ingreso',
    'tendencia_prediccion',
    'clima',
    'analisis_satelital_riesgo',
    'general',
    'fuera_alcance'
  ];

  if (!categorias.includes(datos.tipo_consulta)) {
    throw new Error(
      'tipo_consulta no valido: ' +
      String(datos.tipo_consulta)
    );
  }

  if (
    datos.fecha != null &&
    !/^\d{4}-\d{2}-\d{2}$/.test(
      String(datos.fecha)
    )
  ) {
    throw new Error(
      'Fecha invalida. Se espera YYYY-MM-DD o null.'
    );
  }

  return datos;
}

// ========================================
// 2. NORMALIZACION DE TEXTO
// ========================================

function normalizar(texto) {
  return String(texto ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();
}

// ========================================
// 3. REGIONES
// ========================================

const regiones = [
  'junin',
  'lima',
  'arequipa',
  'cusco',
  'puno',
  'huanuco',
  'ica',
  'piura',
  'la libertad',
  'lambayeque',
  'ancash',
  'ayacucho',
  'cajamarca',
  'huancavelica',
  'apurimac',
  'tacna',
  'moquegua',
  'tumbes',
  'amazonas',
  'san martin',
  'ucayali',
  'loreto',
  'madre de dios',
  'pasco'
];

// ========================================
// 4. PROCESAR CLASIFICACIONES
// ========================================

return $input.all().map(item => {

  const datos = extraerObjeto(
    item.json.output ?? item.json.text
  );

  const preguntaOriginal = String(
    $('Webhook').first().json.body?.pregunta ??
    $('Webhook').first().json.body?.question ??
    ''
  );

  const pregunta = normalizar(preguntaOriginal);

  if (!pregunta) {
    throw new Error(
      'No se encontro la pregunta del usuario.'
    );
  }

  const tipoOriginal = datos.tipo_consulta;

  // ------------------------------------
  // DETECCION DE INTENCIONES
  // ------------------------------------

  const hablaDeClima =
    /\b(clima|climatico|meteorologico|tiempo|lluvia|lluvias|precipitacion|precipitaciones|temperatura|temperaturas|humedad|helada|heladas|sequia|pronostico|evapotranspiracion)\b/
      .test(pregunta);

  const hablaDePrecios =
    /\b(precio|precios|costo|costos|costaba|cuesta|cotizacion|cotizaciones|vario|variaron|variacion)\b/
      .test(pregunta);


  const hablaDeVolumen =
    /\b(volumen|volumenes|toneladas|kilogramos ingresados|ingreso|ingresaron|abastecimiento|equivale|equivalen|equivalencia|equivalencias|conversion|convertir|cuantos kilogramos|cuantos kilos|cuantos kg|cuanto pesa|peso de un atado)\b/
      .test(pregunta);

  const consultaEquivalencia =
    /\b(equivale|equivalen|equivalencia|equivalencias|conversion|convertir|cuantos kilogramos|cuantos kilos|cuantos kg|cuanto pesa|peso de un atado)\b/
      .test(pregunta);


  const hablaDeMercados =
    /\b(mercado|mercados|gmml|mmf2|frutas|verduras)\b/
      .test(pregunta);

  const pideResumen =
    /\b(resumen|general|generales|panorama|situacion|como estan|comparacion|compara|comparar)\b/
      .test(pregunta);

  const consultaSemanal =
    /\b(ultimos?\s+7\s+dias|ultimos?\s+siete\s+dias|esta\s+semana|ultima\s+semana|semana\s+pasada|semanal)\b/
      .test(pregunta);

  const consultaSatelital =
    /\b(ndvi|satelital|satelite|satelites|imagen satelital|imagenes satelitales|cobertura vegetal|indice de vegetacion|teledeteccion)\b/
      .test(pregunta);

  // ------------------------------------
  // PRIORIDAD 1 - CONSULTAS RAG
  // ------------------------------------

  const mencionaDocumentos =
    /\b(boletin|boletines|documento|documentos|informe|informes|fuente documental|fuentes documentales)\b/
      .test(pregunta);

  const buscaContenido =
    /\b(informacion|dicen|dice|menciona|mencionan|contiene|contienen|aparece|aparecen|reporta|reportan|explica|explican|almacenado|almacenados|almacenada|almacenadas|segun)\b/
      .test(pregunta);

  // Solo enviar al RAG si la intencion
  // es consultar contenido documental.
  const consultaRAG =
    mencionaDocumentos && buscaContenido;

  if (consultaRAG) {

    datos.tipo_consulta = 'general';

    datos.consulta_semanal = false;

  }

  // ------------------------------------
  // PRIORIDAD 2 - MONITOREO SATELITAL
  // ------------------------------------

  else if (consultaSatelital) {

    // Se conserva la categoria para identificar
    // la solicitud, aunque WF3 sea independiente.
    datos.tipo_consulta =
      'analisis_satelital_riesgo';

    datos.consulta_semanal = false;

  }

  // ------------------------------------
  // PRIORIDAD 3 - CLIMA
  // ------------------------------------

  else if (
    hablaDeClima &&
    !hablaDePrecios &&
    !hablaDeVolumen
  ) {

    datos.tipo_consulta = 'clima';

    datos.consulta_semanal = false;

    if (consultaSemanal) {
      datos.periodo = 'esta semana';
    }

    // Recuperar region explicita si
    // no fue detectada por el agente.
    if (!datos.lugar) {

      const encontrada = regiones.find(r =>
        pregunta.includes(r)
      );

      if (encontrada) {
        datos.lugar = encontrada
          .replace(/\b\w/g, l => l.toUpperCase());
      }
    }

  }

  // ------------------------------------
  // PRIORIDAD 4 - VOLUMEN
  // ------------------------------------
  else if (
    consultaEquivalencia ||
    (hablaDeVolumen && !hablaDePrecios)
  ) {
    datos.tipo_consulta = 'volumen_ingreso';
    datos.consulta_semanal = false;
  }

  // ------------------------------------
  // PRIORIDAD 5 - PRECIOS SEMANALES
  // ------------------------------------

  else if (
    consultaSemanal &&
    hablaDePrecios
  ) {

    datos.tipo_consulta = 'precio_puntual';

    datos.consulta_semanal = true;

  }

  // ------------------------------------
  // PRIORIDAD 6 - MERCADO GENERAL
  // ------------------------------------

  else if (
    hablaDePrecios &&
    (
      /\b(precios?\s+generales?|general(?:es)?\s+de\s+precios?|panorama\s+de\s+precios?)\b/
        .test(pregunta)
      ||
      (
        pideResumen &&
        hablaDeMercados &&
        (
          !datos.producto ||
          /^(producto consultado|producto|general|ninguno)$/i
            .test(String(datos.producto).trim())
        )
      )
    )
  ) {

    datos.tipo_consulta =
      'tendencia_prediccion';

    datos.producto = null;

    datos.consulta_semanal = false;

  }

  // ------------------------------------
  // REGLA FINAL DE SEGURIDAD RAG
  // ------------------------------------

  // Evita que cualquier regla posterior o
  // salida incorrecta del agente desvie
  // una pregunta documental al Pipeline 2.

  if (consultaRAG) {

    datos.tipo_consulta = 'general';

    datos.consulta_semanal = false;

  }

  // ------------------------------------
  // RESULTADO Y DIAGNOSTICO
  // ------------------------------------

  console.log('AGROSMART CLASIFICACION', {
    pregunta: preguntaOriginal,
    clasificacion_agente: tipoOriginal,
    clasificacion_final: datos.tipo_consulta,
    consulta_rag: consultaRAG,
    consulta_satelital: consultaSatelital
  });

  return {
    json: {
      ...item.json,

      output: JSON.stringify(datos),

      producto: datos.producto ?? null,
      periodo: datos.periodo ?? null,
      fecha: datos.fecha ?? null,
      tipo_consulta: datos.tipo_consulta,
      lugar: datos.lugar ?? null,

      consulta_semanal:
        datos.consulta_semanal === true,

      consulta_rag: consultaRAG,

      clasificacion_original: tipoOriginal
    }
  };

});

// AgroSmart S3-03 - Respuesta final para el agricultor
// Nodo: Code - Validar recomendacion S3-03
// Modo: Run Once for All Items

const e = $('Code in JavaScript2').first().json;
const modelo = String($input.first()?.json?.text ?? $input.first()?.json?.output ?? '').trim();

function num(valor) {
  if (valor === null || valor === undefined || valor === '') return null;
  const n = Number(valor);
  return Number.isFinite(n) ? n : null;
}

function nf(valor, max = 2, min = 2) {
  const n = num(valor);
  return n === null ? 'sin dato' : n.toLocaleString('es-PE', {
    minimumFractionDigits: min,
    maximumFractionDigits: max
  });
}

function fechaEs(valor) {
  const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(valor ?? ''));
  if (!m) return 'fecha no disponible';

  const meses = [
    'enero','febrero','marzo','abril','mayo','junio',
    'julio','agosto','septiembre','octubre','noviembre','diciembre'
  ];

  const mes = Number(m[2]);
  if (mes < 1 || mes > 12) return 'fecha no disponible';

  return `${Number(m[3])} de ${meses[mes - 1]} de ${m[1]}`;
}

function relacion(actual, promedio) {
  const a = num(actual);
  const b = num(promedio);

  if (a === null || b === null || b <= 0) {
    return 'No hay comparación disponible.';
  }

  if (Math.abs(a - b) < 0.00001) {
    return 'Está al nivel de su promedio.';
  }

  return `Está ${a > b ? 'por encima' : 'por debajo'} de su promedio.`;
}

// Consultas generales de mercado
if (e.modo !== 'especifico') {
  return [{
    json: {
      text: modelo || 'No se pudo generar el resumen general.',
      estado_recomendacion: e.estado_recomendacion ?? 'no_aplica'
    }
  }];
}

const d = e.datos ?? null;

const producto =
  e.producto_solicitado ||
  d?.producto ||
  'el producto solicitado';

const permitidas = new Set([
  'Vender ahora',
  'Esperar y monitorear',
  'Vender parcialmente y monitorear'
]);

const suficiente =
  e.estado_recomendacion === 'suficiente' &&
  d !== null &&
  permitidas.has(e.decision_sugerida);

const lineas = [
  `Evaluación comercial de ${producto} — GMML`
];

// Mostrar primero la recomendacion
lineas.push(
  suficiente
    ? `\nRECOMENDACIÓN: ${e.decision_sugerida.toUpperCase()}`
    : '\nRECOMENDACIÓN: DATOS INSUFICIENTES'
);

// Mostrar los indicadores disponibles
if (d) {
  lineas.push(
    `\nÚltimo precio: S/ ${nf(d.precio_actual)} por ${d.unidad || 'unidad no indicada'} (${fechaEs(d.fecha_ultimo_registro)}).`,

    `Promedio de 7 registros de precio: S/ ${nf(d.precio_promedio_7)}; promedio de 30: S/ ${nf(d.precio_promedio_30)}. ${relacion(d.precio_actual, d.precio_promedio_7)}`,

    `\nÚltimo volumen registrado: ${nf(d.volumen_ultimo_t, 3, 0)} toneladas (${fechaEs(d.fecha_ultimo_volumen)}).`,

    `Promedio de 7 registros de volumen: ${nf(d.volumen_promedio_7_t, 3, 0)} toneladas; promedio de 30: ${nf(d.volumen_promedio_30_t, 3, 0)}. ${relacion(d.volumen_ultimo_t, d.volumen_promedio_7_t)}`
  );

  const tendencia = {
    alza: 'subió',
    baja: 'bajó',
    estable: 'se mantuvo'
  }[d.tendencia_precio];

  if (tendencia) {
    lineas.push(
      `Respecto del precio anterior (S/ ${nf(d.precio_anterior)}), el precio ${tendencia}.`
    );
  }
}

// Escenario 1: informacion suficiente
if (suficiente) {
  lineas.push('\n¿Por qué esta recomendación?');

  if (e.decision_sugerida === 'Esperar y monitorear') {
    lineas.push(
      'El precio está relativamente débil y/o la oferta es elevada según los indicadores analizados. Esto no garantiza una recuperación futura.'
    );

    lineas.push(
      '\n¿Qué significa esperar y monitorear?',
      '• Revisar el siguiente boletín disponible de MIDAGRI y comprobar si el precio cambia.',
      '• Observar si disminuye o aumenta el volumen que ingresa al mercado.',
      '• Comparar el costo de conservar la cosecha con el precio que ofrecen los compradores. Si no es viable esperar, evaluar una venta parcial.'
    );

  } else if (e.decision_sugerida === 'Vender ahora') {
    lineas.push(
      'Las reglas del prototipo identifican señales favorables para comercializar con los indicadores disponibles.'
    );

    lineas.push(
      '\n¿Qué puedes hacer ahora?',
      '• Pedir cotizaciones a compradores y comparar el precio neto ofrecido.',
      '• Revisar transporte, comisiones y otros costos antes de confirmar la venta.',
      '• Verificar el próximo boletín para detectar cambios en precio y abastecimiento.'
    );

  } else {
    lineas.push(
      'Los indicadores no dan una señal suficientemente clara para vender todo o esperar con toda la cosecha.'
    );

    lineas.push(
      '\n¿Qué puedes hacer ahora?',
      '• Evaluar vender una parte para obtener liquidez, según tus necesidades.',
      '• Revisar precios y volúmenes en los próximos boletines.',
      '• Considerar el estado del producto y el costo de guardar el resto.'
    );
  }

// Escenario 2: informacion insuficiente
} else {
  lineas.push(
    '\nNo es posible emitir una recomendación de venta sólida con los datos disponibles.'
  );

  const faltantes = Array.isArray(e.faltantes)
    ? e.faltantes
    : [];

  if (faltantes.length) {
    lineas.push('\n¿Qué falta para recomendar?');

    for (const motivo of faltantes) {
      lineas.push(`• ${String(motivo)}`);
    }
  }

  if (
    Array.isArray(e.coincidencias) &&
    e.coincidencias.length
  ) {
    lineas.push(
      'Presentaciones disponibles: ' +
      e.coincidencias
        .map(x => `${x.producto} (${x.unidad})`)
        .join(', ') + '.'
    );
  }

  lineas.push(
    'Revisa el boletín más reciente y considera los costos de conservación antes de decidir.'
  );
}

// Cierre de la respuesta
lineas.push(
  '\nEsta evaluación es orientativa y se basa en los registros disponibles en AgroSmart; no garantiza precios futuros.'
);

return [{
  json: {
    text: lineas.join('\n'),
    estado_recomendacion: e.estado_recomendacion ?? null
  }
}];

const registros = $input.all()
  .map(item => item.json)
  .filter(r => r.fecha && r.ubicacion);

const historicos = registros.filter(r =>
  String(r.tipo_dato).toLowerCase() === 'historico'
);

const pronosticos = registros.filter(r =>
  String(r.tipo_dato).toLowerCase() === 'pronostico'
);

historicos.sort((a, b) =>
  String(b.fecha).localeCompare(String(a.fecha))
);

pronosticos.sort((a, b) =>
  String(a.fecha).localeCompare(String(b.fecha))
);

const ubicacion =
  registros[0]?.ubicacion ?? 'No especificada';

const ciudad =
  registros[0]?.ciudad_referencia ?? null;

return [{
  json: {
    ubicacion,
    ciudad_referencia: ciudad,

    dias_disponibles: pronosticos.length,

    desde: pronosticos[0]?.fecha ?? null,

    hasta: pronosticos.at(-1)?.fecha ?? null,

    ultimo_historico: historicos[0] ?? null,

    pronostico_7_dias: pronosticos,

    tiene_pronostico: pronosticos.length > 0,

    total_registros: registros.length
  }
}];

// AGROSMART WF2 - RESPUESTA DE EQUIVALENCIAS
// Sin consumo de tokens de IA.

const filas = $input.all().map(item => item.json);

const validas = filas.filter(r =>
  r.producto &&
  r.unidad &&
  Number(r.equivalencia_kg) > 0
);

const pregunta = String(
  $('Webhook').first().json.body?.pregunta || ''
);

function formatear(numero, decimales = 2) {
  return Number(numero).toLocaleString('es-PE', {
    minimumFractionDigits: decimales,
    maximumFractionDigits: decimales
  });
}

if (validas.length === 0) {
  return [{
    json: {
      respuesta:
        'No se encontró una equivalencia comercial ' +
        'válida para el producto y la presentación ' +
        'solicitados en GMML ni MMF2.',
      estado: 'sin_datos',
      pregunta
    }
  }];
}

const respuestas = validas.map(r => {

  const kg = Number(r.equivalencia_kg);
  const gramos = kg * 1000;

  const fecha = String(r.fecha || '').slice(0, 10);

  return (
    `**${r.mercado}**\n` +
    `Un(a) ${String(r.unidad).toLowerCase()} de ` +
    `**${r.producto}** equivale a ` +
    `**${formatear(kg)} kg** ` +
    `(${formatear(gramos, 0)} gramos).\n` +
    `Fecha del registro: ${fecha}.`
  );
});

return [{
  json: {
    respuesta:
      respuestas.join('\n\n') +
      '\n\nFuente: MIDAGRI / AgroSmart Insights.',
    estado: 'ok',
